package com.example.microsave.repayment.entity;
import com.example.microsave.loan.entity.Loan;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDate;
@Entity@Table(name="repayments")public class Repayment{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="loan_id",nullable=false)private Loan loan;@Column(nullable=false,precision=12,scale=2)private BigDecimal amount;@Column(nullable=false)private LocalDate repaymentDate;@Column(length=40)private String paymentMethod;@Column(length=300)private String remarks;public Repayment(){}public Long getId(){return id;}public Loan getLoan(){return loan;}public void setLoan(Loan v){loan=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public LocalDate getRepaymentDate(){return repaymentDate;}public void setRepaymentDate(LocalDate v){repaymentDate=v;}public String getPaymentMethod(){return paymentMethod;}public void setPaymentMethod(String v){paymentMethod=v;}public String getRemarks(){return remarks;}public void setRemarks(String v){remarks=v;}}
